const allAnalyses = $input.all();
const meta = $input.first().json.meta 
  ?? $('Add Metadata').item.json; // Fallback
let finalDocument = meta.cleanMarkdown || '';

const analysesWithIndex = allAnalyses
  .map(item => ({
    imageIndex:
      item.json.imageIndex ??
      item.json.image?.imageIndex ??
      item.json.meta?.imageIndex ??
      item.json.data?.imageIndex ??
      item.json.index,
    content: item.json.message?.content ?? item.json.content ?? ""
  }))
  .filter(a => Number.isInteger(a.imageIndex) && a.content.trim().length > 0)
  .sort((a, b) => a.imageIndex - b.imageIndex);

const analysisMap = {};
for (const a of analysesWithIndex) {
  analysisMap[a.imageIndex] = a.content;
}

// Token normalisieren
finalDocument = finalDocument.replace(/##\s*FIGURE_(\d+)\s*##/g, '##FIGURE_$1##');

const parts = finalDocument.split(/##FIGURE_(\d+)##/);

finalDocument = '';
for (let i = 0; i < parts.length; i++) {
  if (i % 2 === 0) {
    finalDocument += parts[i];
  } else {
    const index = parseInt(parts[i]);
    const analysis = analysisMap[index];
    if (analysis) {
      finalDocument += `\n---\n> ### 🖼️ KI-BILDANALYSE (ABBILDUNG ${index})\n>\n${analysis.split('\n').map(line => '> ' + line).join('\n')}\n---\n`;
    } else {
      finalDocument += `[Keine Analyse für Abbildung ${index}]`;
    }
  }
}

return [{
  json: {
    ...meta,
    fileName: meta.fileName || $json.fileName,
    message: { content: finalDocument }
  }
}];

return [{
