}

return results;

const items = $input.all();
const splitFilesItem = $('Split Files').item;
const formTriggerItem = $('Form Trigger').first();

const originalFileName = splitFilesItem.binary?.data?.fileName || "unnamed-file";

return items.map(item => ({
  json: {
    ...item.json,
    message: {
      content: item.json.cleaned || item.json.cleanMarkdown || item.json.message?.content || ""
    },
    originalFileName: originalFileName,
    directory: formTriggerItem.json["Verzeichnis"] || "upload",
    hasImages: item.json.hasImages || false,
    images: item.json.images || [],
    cleanMarkdown: item.json.cleanMarkdown || item.json.cleaned || ""
  }
}));

const replaceUmlauts = (str) => {
  if (!str) return str;
  return str
    .replace(/ä/g, 'ae').replace(/ö/g, 'oe').replace(/ü/g, 'ue')
    .replace(/Ä/g, 'Ae').replace(/Ö/g, 'Oe').replace(/Ü/g, 'Ue')
    .replace(/ß/g, 'ss')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '');
};

const toS3Safe = (str) => {
  return replaceUmlauts(str).replace(/[^a-zA-Z0-9/_-]/g, '-').toLowerCase();
};

const rawFileName = $json.originalFileName || "document";
const rawDirectory = $json.directory || "upload";
const cleanedContent = $json.message?.content || "";

return [{
  json: {
    message: {
      content: cleanedContent
    },
    directory: toS3Safe(rawDirectory),
    originalFileName: toS3Safe(rawFileName.replace(/\.[^/.]+$/, '')) + '.md'
  }
}];

// cleaned aus dem vorherigen Cleanup Markdown Node holen
let cleaned = $json.cleaned || "";

// Schritt A: Nach Umlaut ("ä ltige" → "ältige") - 2x für Ketten
cleaned = cleaned.replace(/([äöüÄÖÜß])\s+([a-zA-ZäöüÄÖÜß])/gu, '$1$2');
cleaned = cleaned.replace(/([äöüÄÖÜß])\s+([a-zA-ZäöüÄÖÜß])/gu, '$1$2');

// Schritt B: Vor Umlaut ("vielf ä" → "vielä") - 2x für Ketten
cleaned = cleaned.replace(/([a-zA-ZäöüÄÖÜß])\s+([äöüÄÖÜß])/gu, '$1$2');
cleaned = cleaned.replace(/([a-zA-ZäöüÄÖÜß])\s+([äöüÄÖÜß])/gu, '$1$2');

// Platzhalter-Stabilisierung: Leerzeichen um FIGURE-Token normalisieren
cleaned = cleaned.replace(/##\s*FIGURE_(\d+)\s*##/g, '##FIGURE_$1##');

// Quellen-Abschnitte entfernen (split auf H2-Überschriften, dann filtern)
const sections = cleaned.split(/(?=^## )/m);
cleaned = sections.filter(s => !s.startsWith('## Quellen')).join('');

// Bild-Daten aus Extract Images holen (werden von Cleanup Markdown nicht durchgereicht)
const extractItem = $('Extract Images').item;

// Korrektes Array-Return (war vorher plain Object – n8n-Fehlerquelle)
return [{
  json: {
    ...$json,
    cleaned: cleaned.trim(),
    cleanMarkdown: cleaned.trim(),
    hasImages: extractItem.json.hasImages || false,
    images: extractItem.json.images || []
  }
}];

const images = $json.images || [];
const supportedImages = images.filter(img => img.isSupported && img.base64Image);

if (supportedImages.length === 0) {
  return [{ json: { skip: true } }];
}

return supportedImages.map(img => ({
  json: {
    ...img,
    cleanMarkdown: $json.cleanMarkdown,
    fileName: $json.fileName,
    originalFileName: $json.originalFileName,
    directory: $json.directory
  }
}));

// imageIndex aus Prepare Image Loop holen (geht durch Image Verbalizer verloren)
const imageIndex = $('Prepare Image Loop').item.json.imageIndex;

const raw = $json.message?.content || "";

// Thinking-Tags strippen (qwen3-vl gibt manchmal nur Thinking ohne Antwort-Text)
const content = raw.includes('</think>')
  ? raw.split('</think>').pop().trim()
  : raw.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

return [{
  json: {
    imageIndex: imageIndex,
    message: {
      content: content
    }
  }
}];

const content = $json.message?.content || '';

// Interview detection: Timestamp-Marker in Überschriften (WhisperX-Transkripte)
const isInterview = /###\s+.+[\s\S]*?<!--\s*ts:/.test(content);

// Wissensbausteine detection: nummeriertes Heading mit mind. zwei Segmenten + trailing dot
// z.B. "## 2.1. Medienbegriff" oder "## 8.2. Mikro- und Makroadaptivität"
const isWissensbausteine = /^##\s+\d+\.\d+[.\s]/m.test(content);

const docType = isInterview ? 'interview'
  : isWissensbausteine ? 'wissensbausteine'
  : 'buchkapitel';

// Bildanalyse-Blöcke entfernen – LLM soll keine KI-generierten Texte als Input bekommen
const cleanedForLLM = content
  .replace(/---\n> ### 🖼️ KI-BILDANALYSE[\s\S]*?---\n/g, '')
  .replace(/#{1,6}\s*🖼️[^\n]*/g, '')
  .trim();

// Alle Überschriften extrahieren (H1-H4) – kompakter Input für Metadaten-Extraktion
const headings = cleanedForLLM
  .split('\n')
  .filter(line => /^#{1,4}\s+/.test(line))
  .join('\n');

// Wissensbausteine: Metadaten sind bekannt → hartcodieren, LLM-Call trotzdem nötig
// (minimaler Dummy-Prompt damit Extract Metadata via LLM nicht fehlschlägt)
if (docType === 'wissensbausteine') {
  return [{ 
    json: { 
      ...$json, 
      doc_type: docType,
      meta_title: 'Wissensbausteine Mediendidaktik',
      meta_authors: 'Berger, Sonja; Götzinger, Benjamin; Schultz-Pernice, Florian',
      meta_year: 2026,
      meta_topic: 'Mediendidaktik, Lerntheorien, Kognitive Belastung, Adaptivität, Unterrichtsmethoden, Digitale Medien, Scaffolding, Feedback, Instruktionsdesign, KI im Unterricht',
      llm_body: {
        model: 'nemotron-3-nano:latest',
        stream: false,
        options: { temperature: 0.0, num_predict: 1 },
        prompt: 'x'  // Dummy-Prompt – Antwort wird in Parse LLM Metadata ignoriert
      }
    } 
  }];
}

// Normalpfad buchkapitel/interview: LLM extrahiert Titel, Autoren, Jahr, Schlagworte
const prompt = "Du bist ein Metadaten-Extraktor. Analysiere den folgenden wissenschaftlichen Text und gib NUR ein JSON-Objekt zurück (kein Markdown, keine Erklärung, kein Text davor oder danach).\n\nFormat:\n{\"title\": \"Vollständiger Titel\", \"authors\": \"Nachname, Vorname; Nachname2, Vorname2\", \"year\": 2024, \"topic\": \"Schlagwort1, Schlagwort2, Schlagwort3, Schlagwort4, Schlagwort5, Schlagwort6, Schlagwort7, Schlagwort8, Schlagwort9, Schlagwort10\"}\n\nRegeln:\n- title: Offizieller Titel des Werks (meist H1)\n- authors: Alle Autoren, Semikolon getrennt, Nachname zuerst. Falls nicht erkennbar: \"\"\n- year: Erscheinungsjahr als Zahl. Falls nicht erkennbar: null\n- topic: Genau 10 prägnante Fachbegriffe zum Inhalt. Alle Begriffe MÜSSEN auf Deutsch sein, keine englischen Begriffe erlaubt.\n\n[ÜBERSCHRIFTEN]:\n"
  + headings.substring(0, 3000) 
  + "\n\n[TEXTANFANG]:\n" + cleanedForLLM.substring(0, 1000)
  + "\n\n[TEXTENDE]:\n" + cleanedForLLM.slice(-800);

const llmBody = {
  model: 'nemotron-3-nano:latest',
  stream: false,  // stream:false – Extract Metadata via LLM nutzt eigenen Agent ohne Timeout
  options: { temperature: 0.1 },
  prompt: prompt
};

return [{ json: { ...$json, doc_type: docType, llm_body: llmBody } }];

const raw = $json.response || '';
const prev = $('Detect Type').first().json;

// Wissensbausteine: hardcodierte Metadaten aus Detect Type direkt nehmen
if (prev.doc_type === 'wissensbausteine') {
  return [{
    json: {
      ...prev,
      meta_title: prev.meta_title || '',
      meta_authors: prev.meta_authors || '',
      meta_year: prev.meta_year || null,
      meta_topic: prev.meta_topic || ''
    }
  }];
}

// Normalpfad buchkapitel/interview
const stripped = raw.includes('</think>')
  ? raw.split('</think>').pop().trim()
  : raw.replace(/<think>[\s\S]*?<\/think>/g, '').trim();

let metadata = { title: '', authors: '', year: null, topic: '' };
try {
  const match = stripped.match(/\{[\s\S]*\}/);
  if (match) {
    metadata = JSON.parse(match[0]);
  }
} catch(e) {
