    ...prev,
    meta_title: metadata.title || '',
    meta_authors: metadata.authors || '',
    meta_year: metadata.year || null,
    meta_topic: metadata.topic || ''
  }
}];

const d = $json;
const content = d.message?.content || '';

const year = d.meta_year ? String(d.meta_year) : 'null';

const frontmatter = [
  '---',
  `title: "${(d.meta_title || '').replace(/"/g, '\'')}"`,
  `authors: "${(d.meta_authors || '').replace(/"/g, '\'')}"`,
