});

// HTTP Request an Ollama /api/generate (Text-only, kein multimodal)
// Modell: nemotron-3-nano (schnell, für JSON-Metadaten-Extraktion ausreichend)
const raw = await new Promise((resolve, reject) => {
  const req = http.request({
    hostname: '172.18.0.1',
    port: 11434,
    path: '/api/generate',  // Generate Endpoint (kein Chat-Format nötig)
    method: 'POST',
    agent: agent,
    headers: {
      'Content-Type': 'application/json',
      'Content-Length': Buffer.byteLength(body)
    }
  }, (res) => {
    let data = '';
    res.on('data', chunk => { data += chunk; });
    res.on('end', () => resolve(data));
  });
  req.on('error', reject);
  req.write(body);
  req.end();
});

